# CSV-only adaptation of P59 Ridge local support mapping to P41's branched reference tree.
# Native reference cells, graph, and Ridge coefficients remain frozen.
WINDOW_CELLS<-100L;WINDOW_STEP<-25L;SENSITIVITY_WINDOWS<-c(60L,100L,160L)
K_INTERVALS<-3L;KMEANS_SEED<-905L;KMEANS_NSTART<-100L
source_file<-sub('^--file=','',grep('^--file=',commandArgs(),value=TRUE)[1]);setwd(dirname(dirname(normalizePath(source_file))))
suppressPackageStartupMessages({library(data.table);library(igraph)})
d<-fread('inputs/original_Ridge_projection.csv');nodes<-fread('inputs/reference_graph_nodes.csv');edges<-fread('inputs/reference_graph_edges.csv');root<-fread('inputs/reference_graph_root.csv')$root_node[1]
stopifnot(!anyDuplicated(d$cell_id),all(c(edges$from,edges$to)%in%nodes$node_id),sum(d$batch!='B3')>0,all(is.finite(d$trajectory_1)),all(is.finite(d$trajectory_2)))
ref<-d$batch!='B3';R<-as.matrix(d[ref,.(trajectory_1,trajectory_2)]);Q<-as.matrix(d[!ref,.(trajectory_1,trajectory_2)])
g<-graph_from_data_frame(as.data.frame(edges[,.(from,to)]),directed=FALSE,vertices=as.data.frame(nodes[,.(node_id)]));Elen<-sqrt((edges$x1-edges$x0)^2+(edges$y1-edges$y0)^2);Elen<-pmax(Elen,1e-12);E(g)$weight<-Elen
rootdist<-as.vector(distances(g,v=root,to=nodes$node_id,weights=Elen));names(rootdist)<-nodes$node_id
# Orient each fitted edge away from the native D0-rooted graph origin.
flip<-rootdist[edges$from]>rootdist[edges$to];from<-ifelse(flip,edges$to,edges$from);to<-ifelse(flip,edges$from,edges$to)
A<-cbind(ifelse(flip,edges$x1,edges$x0),ifelse(flip,edges$y1,edges$y0));B<-cbind(ifelse(flip,edges$x0,edges$x1),ifelse(flip,edges$y0,edges$y1));Evec<-B-A;startdist<-rootdist[from]
project_graph<-function(Z){t(vapply(seq_len(nrow(Z)),function(i){v<-sweep(A,2,Z[i,],function(a,z)z-a);u<-pmax(0,pmin(1,rowSums(v*Evec)/(Elen^2)));C<-A+Evec*u;ds<-rowSums(sweep(C,2,Z[i,],'-')^2);j<-which.min(ds);c(graph_distance=unname(startdist[j]+u[j]*Elen[j]),graph_x=C[j,1],graph_y=C[j,2],distance_to_graph=sqrt(ds[j]),edge_id=unname(edges$edge_id[j]))},numeric(5)))}
rp<-project_graph(R);tips<-nodes$node_id[nodes$degree==1&nodes$node_id!=root]
# Each root-to-tip arm gets its own sliding support windows. Shared trunk cells may
# occur on multiple arms, but no polygon is built by combining distinct branch arms.
arm_edges<-lapply(tips,function(tip){v<-as_ids(shortest_paths(g,from=root,to=tip,weights=Elen,output='vpath')$vpath[[1]]);paste(head(v,-1),tail(v,-1),sep='|')})
edge_key<-paste(from,to,sep='|');names(arm_edges)<-tips
make_support<-function(k,step){polys<-list();info<-list();for(tip in names(arm_edges)){ids<-which(edge_key[rp[,'edge_id']]%in%arm_edges[[tip]]);ids<-ids[order(rp[ids,'graph_distance'],d$cell_id[which(ref)[ids]])];n<-length(ids);stopifnot(n>=3);kk<-min(k,n);starts<-unique(c(seq(1,n-kk+1,by=step),n-kk+1));for(s in starts){H<-R[ids[s:(s+kk-1)],,drop=FALSE];hull<-H[chull(H),,drop=FALSE];polys[[length(polys)+1L]]<-hull;info[[length(info)+1L]]<-data.table(polygon_id=length(polys),arm_tip=tip,window_start=s,window_cells=kk,reference_arm_cells=n)}};list(polys=polys,info=rbindlist(info))}
inside<-function(z,H){aa<-H;ee<-H[c(2:nrow(H),1),,drop=FALSE]-aa;cross<-ee[,1]*(z[2]-aa[,2])-ee[,2]*(z[1]-aa[,1]);all(cross>=-1e-9)||all(cross<=1e-9)}
solve_constrained<-function(Z,polys){aa<-do.call(rbind,polys);bb<-do.call(rbind,lapply(polys,function(h)h[c(2:nrow(h),1),,drop=FALSE]));ee<-bb-aa;t(vapply(seq_len(nrow(Z)),function(i){z<-Z[i,];if(any(vapply(polys,function(h)inside(z,h),logical(1))))return(c(z[1],z[2],0));u<-pmax(0,pmin(1,rowSums(sweep(aa,2,z,function(a,z)z-a)*ee)/pmax(rowSums(ee^2),1e-12)));C<-aa+ee*u;dist<-rowSums(sweep(C,2,z,'-')^2);j<-which.min(dist);c(C[j,1],C[j,2],sqrt(dist[j]))},numeric(3)))}
# Reference-only monotone calibration from graph distance to native Monocle PT.
ag<-aggregate(d$pseudotime[ref],list(graph_distance=rp[,1]),median);names(ag)[2]<-'pt';ag<-ag[order(ag$graph_distance),];fit<-isoreg(ag$graph_distance,ag$pt);kn<-data.table(graph_distance=fit$x,native_pt=cummax(fit$yf));bounds<-range(d$pseudotime[ref]);kn<-rbind(data.table(graph_distance=0,native_pt=bounds[1]),kn[graph_distance>0],fill=TRUE);kn<-kn[order(graph_distance)][!duplicated(graph_distance)];getpt<-function(x)approx(kn$graph_distance,kn$native_pt,xout=x,rule=2)$y
models<-list();audit<-list()
for(k in SENSITIVITY_WINDOWS){sup<-make_support(k,if(k==WINDOW_CELLS)WINDOW_STEP else max(1,round(k/4)));z<-solve_constrained(Q,sup$polys);gp<-project_graph(z[,1:2,drop=FALSE]);pt<-getpt(gp[,1]);covered<-sum(vapply(seq_len(nrow(R)),function(i)any(vapply(sup$polys,function(h)inside(R[i,],h),logical(1))),logical(1)));models[[as.character(k)]]<-list(support=sup,z=z,gp=gp,pt=pt);audit[[as.character(k)]]<-data.table(window_cells=k,polygons=length(sup$polys),adjusted_cells=sum(z[,3]>1e-8),median_shift=median(z[,3]),max_shift=max(z[,3]),reference_cells_covered=covered)}
m<-models[[as.character(WINDOW_CELLS)]];out<-copy(d);out[,`:=`(original_Ridge_1=trajectory_1,original_Ridge_2=trajectory_2,original_Ridge_pseudotime=pseudotime,original_progress_state=progress_state)]
out[!ref,`:=`(trajectory_1=m$z[,1],trajectory_2=m$z[,2],pseudotime=m$pt)];out[,mapping_shift_distance:=0];out[!ref,mapping_shift_distance:=m$z[,3]];out[,constraint_active:=mapping_shift_distance>1e-8]
gp<-project_graph(as.matrix(out[,.(trajectory_1,trajectory_2)]));out[,`:=`(graph_x=gp[,2],graph_y=gp[,3],graph_distance=gp[,1],distance_to_reference_graph=gp[,4],nearest_reference_edge=gp[,5])]
maxgraph<-max(rootdist);out[,t_graph:=graph_distance/maxgraph]
# K=3 is fit on reference cells alone; all cells receive frozen midpoint boundaries.
set.seed(KMEANS_SEED);km<-kmeans(out$t_graph[ref],centers=K_INTERVALS,nstart=KMEANS_NSTART,iter.max=1000);centers<-sort(drop(km$centers));cutpoints<-(head(centers,-1)+tail(centers,-1))/2
state_names<-c('Early','Middle','Late');assign_interval<-function(x,b)as.character(cut(x,c(-Inf,b,Inf),labels=state_names,right=TRUE))
out[,progress_state:=assign_interval(t_graph,cutpoints)];out[,reference_K3_interval:=progress_state]
native_cuts<-quantile(out$pseudotime[ref],c(1/3,2/3));out[,interval_native_PT_tertiles:=assign_interval(pseudotime,native_cuts)];out[,interval_tgraph_tertiles:=assign_interval(t_graph,quantile(t_graph[ref],c(1/3,2/3)))];out[,interval_equal_length:=assign_interval(t_graph,c(1/3,2/3))]
out[,trajectory_coordinate_source:=ifelse(ref,'Osi_DDRTree_reference','Ridge_local_support_constrained')]
out[,outside_reference_PT_range:=pseudotime<bounds[1]|pseudotime>bounds[2]]
# Existing feature-space support flag stays as an independent extrapolation diagnostic.
stopifnot(all(vapply(which(!ref),function(i)any(vapply(m$support$polys,function(h)inside(c(out$trajectory_1[i],out$trajectory_2[i]),h),logical(1))),logical(1))),all(out$pseudotime>=bounds[1]-1e-9&out$pseudotime<=bounds[2]+1e-9),all(out$trajectory_1[ref]==d$trajectory_1[ref]),all(out$trajectory_2[ref]==d$trajectory_2[ref]),all(out$pseudotime[ref]==d$pseudotime[ref]))
wr<-function(x,n)fwrite(x,file.path('tables',n),na='')
wr(out,'all_cells_constrained_mapping.csv');wr(out[!ref],'OsiTCD_constrained_mapping.csv');wr(out[constraint_active==TRUE],'constraint_active_cells.csv');wr(kn,'reference_graph_distance_to_native_pseudotime.csv');wr(rbindlist(audit),'support_width_sensitivity.csv')
polydata<-rbindlist(lapply(seq_along(m$support$polys),function(i){H<-m$support$polys[[i]];data.table(polygon_id=i,vertex=seq_len(nrow(H)),x=H[,1],y=H[,2])}));wr(polydata,'reference_local_support_polygons.csv');wr(m$support$info,'reference_local_support_windows.csv')
sens<-data.table(cell_id=out$cell_id[!ref]);for(k in SENSITIVITY_WINDOWS){sens[[paste0('pseudotime_k',k)]]<-models[[as.character(k)]]$pt;sens[[paste0('shift_k',k)]]<-models[[as.character(k)]]$z[,3];sens[[paste0('tgraph_k',k)]]<-models[[as.character(k)]]$gp[,1]/maxgraph};wr(sens,'cell_mapping_support_sensitivity.csv')
wr(data.table(interval=state_names,center_t_graph=centers,reference_n=as.integer(table(factor(out$progress_state[ref],levels=state_names)))),'K3_centers_and_reference_counts.csv');wr(data.table(boundary=c('Early_to_Middle','Middle_to_Late'),t_graph=cutpoints,graph_distance=cutpoints*maxgraph),'K3_boundaries.csv')
stability<-rbindlist(lapply(1:20,function(seed){set.seed(seed);ff<-kmeans(out$t_graph[ref],centers=3,nstart=20,iter.max=1000);cc<-sort(drop(ff$centers));bb<-(head(cc,-1)+tail(cc,-1))/2;data.table(seed=seed,boundary1=bb[1],boundary2=bb[2],changed_reference=sum(assign_interval(out$t_graph[ref],bb)!=out$progress_state[ref]),changed_query=sum(assign_interval(out$t_graph[!ref],bb)!=out$progress_state[!ref]))}));wr(stability,'K3_initialization_stability.csv')
# Matched true-day composition; alternatives disclose boundary sensitivity.
methods<-c(K3='progress_state',native_PT_tertiles='interval_native_PT_tertiles',tgraph_tertiles='interval_tgraph_tertiles',equal_tgraph_length='interval_equal_length');tests<-list();composition<-list()
for(method in names(methods))for(day0 in c('D3','D8')){z<-out[day==day0];tb<-table(factor(ifelse(z$batch=='B3','Osi+TCD','Osi'),levels=c('Osi','Osi+TCD')),factor(z[[methods[[method]]]],levels=state_names));chi<-suppressWarnings(chisq.test(tb,correct=FALSE));small<-min(chi$expected)<5;pv<-if(small)fisher.test(tb)$p.value else chi$p.value;tests[[length(tests)+1]]<-data.table(method=method,day=day0,test=if(small)'Fisher exact'else'Pearson chi-square',p_value=pv,Cramers_V=sqrt(as.numeric(chi$statistic)/sum(tb)),minimum_expected_count=min(chi$expected));ct<-as.data.table(as.data.frame(tb));setnames(ct,c('regimen','interval','n'));ct[,`:=`(method=method,day=day0)];ct[,percent:=100*n/sum(n),by=regimen];composition[[length(composition)+1]]<-ct}
tests<-rbindlist(tests);tests[,BH_FDR_within_method:=p.adjust(p_value,'BH'),by=method];tests[,BH_FDR_all_8_comparisons:=p.adjust(p_value,'BH')];wr(tests,'reference_interval_comparison_tests.csv');wr(rbindlist(composition),'reference_interval_composition.csv')
width_tests<-rbindlist(lapply(SENSITIVITY_WINDOWS,function(k){z<-copy(out);z[!ref,progress_state:=assign_interval(sens[[paste0('tgraph_k',k)]],cutpoints)];rbindlist(lapply(c('D3','D8'),function(day0){v<-z[day==day0];tb<-table(factor(ifelse(v$batch=='B3','Osi+TCD','Osi'),levels=c('Osi','Osi+TCD')),factor(v$progress_state,levels=state_names));chi<-suppressWarnings(chisq.test(tb,correct=FALSE));data.table(window_cells=k,day=day0,p_value=if(min(chi$expected)<5)fisher.test(tb)$p.value else chi$p.value,Cramers_V=sqrt(as.numeric(chi$statistic)/sum(tb)),query_Early=sum(v$batch=='B3'&v$progress_state=='Early'),query_Middle=sum(v$batch=='B3'&v$progress_state=='Middle'),query_Late=sum(v$batch=='B3'&v$progress_state=='Late'))}))}));width_tests[,BH_FDR_within_window:=p.adjust(p_value,'BH'),by=window_cells];wr(width_tests,'support_width_K3_composition_sensitivity.csv')
wr(out[!ref,.(n=.N,constraint_active=sum(constraint_active),median_shift=median(mapping_shift_distance),max_shift=max(mapping_shift_distance),Early=sum(progress_state=='Early'),Middle=sum(progress_state=='Middle'),Late=sum(progress_state=='Late')),by=day],'query_mapping_summary.csv')
wr(data.table(metric=c('window_cells','window_step','n_reference','n_query','reference_graph_tips','reference_graph_branch_nodes','reference_calibration_RMSE','reference_graph_distance_native_PT_Spearman','reference_min_PT','reference_max_PT','graph_max_distance'),value=c(WINDOW_CELLS,WINDOW_STEP,sum(ref),sum(!ref),length(tips),sum(nodes$degree>2),sqrt(mean((getpt(rp[,1])-d$pseudotime[ref])^2)),cor(rp[,1],d$pseudotime[ref],method='spearman'),bounds,maxgraph)),'mapping_parameters.csv')
fwrite(out,'inputs/reference_and_projected_cells.csv')
wr(data.table(check=c('all query within branch-aware local support','all reference cells covered','reference coordinates and native PT unchanged','all query PT within native reference range','K3 fit reference only'),passed=c(TRUE,all(rbindlist(audit)$reference_cells_covered==sum(ref)),TRUE,TRUE,TRUE)),'local_support_validation.csv')
cat('Root:',root,'Reference cells:',sum(ref),'query:',sum(!ref),'\n');print(rbindlist(audit));print(tests[method=='K3']);print(out[!ref,.(n=.N,active=sum(constraint_active)),by=day])
